请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-008

=== 用户原始指令 (query.txt) ===
弄个睡眠卡 文字叠背景图上那种 点开能跳应用 能看日历 有红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个睡眠卡 文字叠背景图上那种 点开能跳应用 能看日历 有红色危险提示",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/router/sleepDetail"
      }
    }
  ],
  "dataModelSchema": {
    "sleep": {
      "title": {
        "type": "string",
        "description": "睡眠卡标题",
        "sampleValue": "睡眠监督"
      },
      "durationText": {
        "type": "string",
        "description": "昨晚睡眠时长展示文本",
        "sampleValue": "6小时20分"
      },
      "alertText": {
        "type": "string",
        "description": "红色危险提示文案",
        "sampleValue": "深睡不足"
      },
      "hintText": {
        "type": "string",
        "description": "点击后进入睡眠详情的短提示",
        "sampleValue": "轻触查看睡眠详情"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程唯一标识符",
              "sampleValue": "calendar_sample_001"
            },
            "title": {
              "type": "string",
              "description": "日程标题",
              "sampleValue": "晨间复盘"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间",
              "sampleValue": "09:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间",
              "sampleValue": "09:30"
            },
            "eventLocation": {
              "type": "string",
              "description": "日程发生位置",
              "sampleValue": "健康日历"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠监督图标，适合用作睡眠卡的背景视觉锚点或主识别图标。"
    },
    {
      "src": "resources/base/media/icon_schedule2.png",
      "description": "日程图标，适合用于日历或当日安排入口的识别。"
    }
  ]
}

